function quizSection(unit){return heading('立即練習','先用觀察推理，最後才選答案','每節 8 題原創觀念與圖像判讀題，可連續作答。')+`<div class="wx-question" id="wxMiniQuiz"><h3>本節小練習</h3><div id="wxMiniArea"></div></div>`}
function miniQuiz(unit){let state={n:0,correct:0,chosen:-1,locked:false};const pool=WEATHER_QUESTIONS[unit];const zone=document.getElementById('wxMiniArea');if(!zone)return;
 function render(){let q=pool[state.n];zone.innerHTML=`<div class="wx-exam-meta"><span>第 ${state.n+1}／${pool.length} 題</span><span>目前答對 <b>${state.correct}</b> 題</span></div><h3>${q[0]}</h3>${diagramFor(q[4])}<div class="wx-optlist">${q[1].map((o,i)=>`<button class="wx-opt" type="button" data-opt="${i}" aria-pressed="false">${'ABCD'[i]}. ${o}</button>`).join('')}</div><div id="wxMiniFeedback"></div><div class="wx-hero-cta"><button class="wx-go" id="wxMiniCheck">確認答案</button><button class="wx-go secondary" id="wxMiniNext">${state.n===pool.length-1?'查看本節結果':'下一題 →'}</button></div>`;
 zone.querySelectorAll('[data-opt]').forEach(b=>b.addEventListener('click',()=>{if(state.locked)return;state.chosen=+b.dataset.opt;zone.querySelectorAll('[data-opt]').forEach(btn=>btn.setAttribute('aria-pressed',btn===b?'true':'false'))}));
 zone.querySelector('#wxMiniCheck').onclick=()=>{if(state.locked||state.chosen<0){if(state.chosen<0)zone.querySelector('#wxMiniFeedback').textContent='先選一個答案。';return}state.locked=true;if(state.chosen===q[2])state.correct++;zone.querySelectorAll('[data-opt]').forEach(b=>{let i=+b.dataset.opt;b.disabled=true;(i===q[2]?b.classList.add('correct'):i===state.chosen?b.classList.add('wrong'):null)});zone.querySelector('#wxMiniFeedback').innerHTML=`<div class="wx-answer"><b>${state.chosen===q[2]?'答對了！':'這題可以救回來。正確答案：'+('ABCD'[q[2]])}</b><p>${q[3]}</p></div>`};
 zone.querySelector('#wxMiniNext').onclick=()=>{if(!state.locked){zone.querySelector('#wxMiniFeedback').textContent='先確認這題的答案，再往下一題。';return}if(state.n===pool.length-1){zone.innerHTML=`<h3>本節完成：${state.correct}／${pool.length} 題</h3><p>${state.correct>=6?'你已能判讀主要題型。':'看懂錯題原因後，再練習就會更好。'}</p>${btn(unit,'重練本節圖像課程')}${btn('exam','試試第二次段考')}`;bind()}else{state.n++;state.locked=false;state.chosen=-1;render()}};
 }render();}
function diagramFor(kind){if(!kind)return'';if(kind==='pressure')return `<div style="max-width:640px;margin:10px 0">${pressureChart(10)}</div>`;
 if(kind==='temperature')return `<div style="max-width:640px;margin:10px 0">${tempChart(50)}</div>`;
 if(kind==='vapor')return `<div style="max-width:640px;margin:10px 0">${vaporChart(20,12)}</div>`;
 if(['cold','warm','stationary','occluded'].includes(kind))return `<div style="max-width:640px;margin:10px 0">${frontSvg(kind)}</div>`;
 if(kind==='station')return stationSvg(136);
 if(kind==='wind')return windSvg('surface');
 if(kind==='rain')return rainSvg('mountain');
 if(kind==='breeze')return breezeSvg('day');
 if(kind==='foehn')return foehnSvg(4000);
 if(kind==='monsoon')return monsoonSvg('summer');
 return'';
}
function inversionSvg(kind){const inversion=kind==='inversion';let p=inversion?'M100 248 L260 170 L380 210 L515 145':'M100 120 L260 175 L380 210 L515 250';return vsvg(`<rect width="640" height="300" fill="#e6f5ff"/><path d="M0 250 Q165 230 320 254 Q440 225 640 252 L640 300 L0 300Z" fill="#80ad79"/><path d="${p}" stroke="${inversion?'#d35f48':'#246ab0'}" stroke-width="7" fill="none"/><rect x="68" y="32" width="505" height="42" rx="10" fill="#fff"/><text x="90" y="60" fill="#194362" font-size="22" font-weight="bold">${inversion?'清晨逆溫：低層冷、上方較暖':'一般情況：高度增加，氣溫下降'}</text><g font-size="18" fill="#274c6b"><text x="90" y="280">谷底</text><text x="500" y="280">山坡</text></g>${inversion?'<g fill="#777" opacity=".8"><circle cx="190" cy="231" r="11"/><circle cx="223" cy="225" r="14"/><circle cx="260" cy="238" r="10"/></g><text x="297" y="235" fill="#7b3c3c" font-size="18">污染不易散</text>':''}`)}
function rainSvg(kind){const desc={mountain:['地形抬升','海上暖濕氣流遇山坡爬升 → 膨脹冷卻 → 迎風坡雲雨。'],front:['鋒面抬升','冷空氣推擠，暖空氣沿鋒面被迫抬升 → 冷卻成雲雨。'],convection:['對流抬升','白天地面受熱，暖空氣密度較小上升 → 冷卻成雲雷雨。'],convergence:['低壓輻合','近地面水平氣流向低壓中心聚集，向上抬升形成雲雨。']}[kind];let scene='';
 if(kind==='mountain')scene=`<path d="M170 250L350 92L530 250Z" fill="#80ab79"/><path d="M25 210L220 210" stroke="#1683bc" stroke-width="9"/><path d="M210 210 Q268 135 320 95" stroke="#1b8cbe" stroke-width="8" fill="none"/><g fill="#fff" stroke="#8ca9ba"><ellipse cx="325" cy="89" rx="69" ry="26"/></g><text x="400" y="112" fill="#234a64" font-size="19">迎風坡降雨</text>`;
 if(kind==='front')scene=`<path d="M0 230L300 230L430 145L640 145L640 270L0 270Z" fill="#88c5df"/><path d="M100 215 Q310 150 460 110" fill="none" stroke="#e65c5c" stroke-width="9"/><path d="M200 175 L450 175" stroke="#e65c5c" stroke-width="6"/><g fill="white" stroke="#8b9aa6"><ellipse cx="350" cy="100" rx="85" ry="33"/></g><text x="390" y="76" fill="#244969" font-size="19">暖氣團上升</text>`;
 if(kind==='convection')scene=`<rect x="0" y="238" width="640" height="62" fill="#c4a17b"/><circle cx="310" cy="90" r="50" fill="#fff" stroke="#91b7cb"/><path d="M330 244 Q270 204 300 145" stroke="#ed9253" stroke-width="13" fill="none"/><path d="M345 245 Q370 203 348 140" stroke="#ed9253" stroke-width="13" fill="none"/><text x="395" y="220" fill="#244969" font-size="19">地表受熱</text>`;
 if(kind==='convergence')scene=`<rect x="0" y="237" width="640" height="63" fill="#88ad78"/><path d="M90 208 H270 M552 208 H360" stroke="#277ac2" stroke-width="8"/><path d="M290 232 Q306 182 312 112" stroke="#277ac2" stroke-width="8" fill="none"/><g fill="white" stroke="#91b7cb"><ellipse cx="320" cy="88" rx="90" ry="35"/></g><text x="298" y="250" fill="#a42d43" font-size="32" font-weight="bold">L</text>`;
return vsvg(`<rect width="640" height="300" fill="#d9f2ff"/><rect x="18" y="17" width="604" height="42" rx="10" fill="#ffffff"/><text x="30" y="47" font-size="23" font-weight="bold" fill="#143a5c">${desc[0]}</text>${scene}`)}
function foehnSvg(height){let rise=.006*height,down=.01*height;let top=30-rise,end=top+down;return vsvg(`<rect width="640" height="300" fill="#e1f2ff"/><path d="M70 245 L320 65 L570 245 L570 275 L70 275Z" fill="#8ab77e"/><path d="M84 224 Q190 190 275 100" stroke="#238bc5" stroke-width="7" fill="none"/><path d="M368 95 Q450 188 560 225" stroke="#de7144" stroke-width="7" fill="none"/><g font-size="19" font-weight="bold" fill="#163c5b"><text x="70" y="280">迎風坡 30°C</text><text x="290" y="55">山頂 ${top.toFixed(1)}°C</text><text x="418" y="280">背風坡 ${end.toFixed(1)}°C</text></g><text x="125" y="152" fill="#194962" font-size="18">上升冷卻</text><text x="438" y="155" fill="#984b2c" font-size="18">下降增溫</text>`)}
function windSvg(stage){const lines=[98,146,194,242],pressureLabels=['1016','1012','1008','1004'];let arrows='';let note='';
 if(stage==='pressure'){arrows=`<path d="M320 72 V250" stroke="#e65d4a" stroke-width="9"/><polygon points="320,265 305,240 335,240" fill="#e65d4a"/>`;note='氣壓梯度力：高壓（上）→低壓（下），垂直等壓線'}
 if(stage==='geostrophic'){arrows=`<path d="M165 167 H450" stroke="#287dce" stroke-width="10"/><polygon points="468,167 441,152 441,182" fill="#287dce"/><path d="M320 177 V240" stroke="#e65d4a" stroke-width="6"/><path d="M320 157 V94" stroke="#8068ca" stroke-width="6"/>`;note='高空：氣壓梯度力向低壓（下），科氏力向上，風沿等壓線 →'}
 if(stage==='surface'){arrows=`<path d="M165 110 L435 229" stroke="#287dce" stroke-width="10"/><polygon points="459,240 428,219 440,246" fill="#287dce"/><path d="M310 175 V233" stroke="#e65d4a" stroke-width="6"/>`;note='近地面摩擦使風速變慢、偏向效果減弱；風會斜穿等壓線往低壓側'}
return vsvg(`<rect width="640" height="300" fill="#eaf5ff"/>${lines.map((y,i)=>`<line x1="65" y1="${y}" x2="590" y2="${y}" stroke="#6d9bbd" stroke-width="3"/><text x="12" y="${y+5}" font-size="16" fill="#215477">${pressureLabels[i]}</text>`).join('')}<text x="510" y="80" fill="#225477" font-size="16">高壓側</text><text x="510" y="280" fill="#225477" font-size="16">低壓側</text>${arrows}<text x="100" y="28" fill="#225477" font-size="18" font-weight="bold">${note}</text>`)}
function breezeSvg(kind){let day=kind==='day';return vsvg(`<rect width="640" height="300" fill="#dceffa"/><rect x="0" y="215" width="310" height="85" fill="#3e9bc7"/><rect x="310" y="215" width="330" height="85" fill="#c4a279"/><text x="105" y="263" fill="#fff" font-size="28" font-weight="bold">海洋</text><text x="437" y="263" fill="#523c24" font-size="28" font-weight="bold">陸地</text><path d="M${day?'130':'500'} 192 L${day?'505':'135'} 192" stroke="#e56748" stroke-width="10"/><polygon points="${day?'520,192 492,176 492,208':'120,192 148,176 148,208'}" fill="#e56748"/><path d="M${day?'510':'135'} 168 V85" stroke="#2389c6" stroke-width="7"/><path d="M${day?'510':'135'} 84 L${day?'498':'147'} 106 L${day?'522':'123'} 106 Z" fill="#2389c6"/><text x="185" y="52" fill="#1b4a64" font-size="27" font-weight="bold">${day?'白天：海風吹向陸地':'夜晚：陸風吹向海洋'}</text><text x="200" y="100" fill="#1b4a64" font-size="19">${day?'陸地升溫較快':'陸地冷卻較快'}</text>`)}
function monsoonSvg(which){return vsvg(`<rect width="640" height="260" fill="#d5ebfb"/><rect x="25" y="25" width="230" height="205" rx="16" fill="#9bd0ff"/><rect x="380" y="25" width="230" height="205" rx="16" fill="#bdd49e"/><text x="80" y="75" font-size="27" fill="#194766">海洋</text><text x="460" y="75" font-size="27" fill="#194766">大陸</text><path d="M${which==='summer'?470:170} 148 H${which==='summer'?195:445}" stroke="#2479bc" stroke-width="12"/><polygon points="${which==='summer'?'170,148 205,128 205,168':'470,148 435,128 435,168'}" fill="#2479bc"/><text x="182" y="206" font-size="22" fill="#194766">${which==='summer'?'夏季（臺灣西南季風）':'冬季（臺灣東北季風）'}</text>`)}
function cellSvg(which){let high=which==='high', arrows='';for(let a=0;a<360;a+=60){let x=320+135*Math.cos(a*Math.PI/180),y=145+90*Math.sin(a*Math.PI/180);arrows+=`<circle cx="${x}" cy="${y}" r="6" fill="#fff"/>`}
return vsvg(`<rect width="640" height="300" fill="#eaf6ff"/><circle cx="320" cy="150" r="104" fill="${high?'#b6dcff':'#ffcad7'}" stroke="${high?'#2385c5':'#d44c65'}" stroke-width="6"/><text x="295" y="176" font-size="72" fill="${high?'#215bb4':'#c13c50'}" font-weight="bold">${high?'H':'L'}</text><path d="${high?'M390 80 Q470 110 455 190':'M250 80 Q175 110 195 190'}" fill="none" stroke="${high?'#215bb4':'#c13c50'}" stroke-width="9"/><text x="85" y="33" font-size="23" fill="#183f62" font-weight="bold">北半球：${high?'順時針向外輻散，中心下沉':'逆時針向內輻合，中心上升'}</text>${arrows}`)}
function stationSvg(code){const p=decodeStation(code);return vsvg(`<rect width="640" height="300" fill="#eaf6ff"/><circle cx="320" cy="155" r="50" fill="#f9fbff" stroke="#194d75" stroke-width="5"/><path d="M320 105 A50 50 0 0 1 320 205 Z" fill="#263e59"/><path d="M320 155 L395 220 M395 220 L380 207 M382 208 L395 202" stroke="#194d75" stroke-width="6"/><text x="220" y="101" font-size="38" fill="#cf3e4b" font-weight="bold">28</text><text x="211" y="234" font-size="38" fill="#2b7ec5" font-weight="bold">24</text><text x="414" y="110" font-size="37" fill="#284c6d" font-weight="bold">${code}</text><text x="427" y="143" font-size="17" fill="#284c6d">${p.toFixed(1)} hPa</text><text x="350" y="271" font-size="18" fill="#284c6d">風羽杆延伸方向＝風來的方向</text><text x="35" y="30" font-size="18" fill="#284c6d">教學範例：28°C、露點24°C、雲量約半</text>`)}
function decodeStation(str){const n=Math.max(0,Math.min(999,parseInt(str,10)||0));return (n<500?1000:900)+n/10}
