function examPool(version){const chapter3Units=['quake','interior','rocks','drift','plate','taiwan'];const ch3=[];
 for(let i=0;i<chapter3Units.length;i++){let id=chapter3Units[i],count=i<4?2:1;let pool=QUESTIONS.filter(q=>q.unit===id&&(version==='A'?q.level!=='D':q.level!=='A'));let offset=(version==='A'?0:2);for(let j=0;j<count;j++){ch3.push(pool[(offset+j*2)%pool.length]);}}
 // 10 題，從大氣 4 小節各抽 2–3 題；A/B 優先用不同題號
 const counts=version==='A'?[3,3,2,2]:[2,2,3,3],ids=['a1','a2','a3','a4'];const ch4=[];ids.forEach((k,i)=>{const bank=WEATHER_QUESTIONS[k];for(let j=0;j<counts[i];j++){let off=version==='A'?j:(j+4)%bank.length;let r=bank[off];ch4.push({id:'weather-'+k+'-'+off,unit:k,level:'B',stem:r[0],opts:r[1],answer:r[2],explain:r[3],fig:r[4],chapter:4});}});
 return [...ch3.map(q=>({...q,chapter:3})),...ch4].sort((a,b)=>a.chapter-b.chapter || (a.id>b.id?1:-1)).map((q,i)=>({...q,order:i+1}));}
